parameters.jsCode:
// Parse the Gemini response into structured data
const geminiResponse = $input.first().json.text || $input.first().json.output || '';

let parsed;
try {
  // Remove markdown code blocks if present
  let cleaned = geminiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // If JSON parsing fails, try to extract from the text
  parsed = {
    vendor_name: null,
    invoice_date: null,
    total_amount: null,
    category: 'Other',
    line_items: []
  };
}

// Get the original webhook data
const webhookData = $('Webhook').first().json.body;

return [{
  json: {
    invoice_id: webhookData.invoice_id,
    vendor_name: parsed.vendor_name || null,
    invoice_date: parsed.invoice_date || null,
    total_amount: parsed.total_amount ? parseFloat(parsed.total_amount) : null,
    category: parsed.category || 'Other',
    line_items: parsed.line_items || [],
    raw_extraction: geminiResponse,
    status: 'Processed'
  }
}];
